import pytest
from wordfreq import top_words


def test_basico():
    assert top_words("a b a c b a", 2) == [("a", 3), ("b", 2)]


def test_empates_alfabeticos_y_mayusculas():
    assert top_words("Perro gato PERRO árbol Gato", 3) == [("gato", 2), ("perro", 2), ("árbol", 1)]


def test_puntuacion():
    assert top_words("hola, hola! ¿qué tal? tal-vez", 2) == [("hola", 2), ("tal", 2)]


def test_menos_palabras_que_k():
    assert top_words("uno dos", 10) == [("dos", 1), ("uno", 1)]


def test_vacio():
    assert top_words("", 3) == []


def test_k_invalido():
    with pytest.raises(ValueError):
        top_words("a", 0)
